/**
 * @param {number} codePoint
 * @param {import('CJK-util').CodepointRange} range
 * @returns {boolean}
 */
function isCodePointInRange(codePoint, [min, max]) {
    return (codePoint >= min && codePoint <= max);
}

/**
 * @param {number} codePoint
 * @param {import('CJK-util').CodepointRange[]} ranges
 * @returns {boolean}
 */
function isCodePointInRanges(codePoint, ranges) {
    for (const [min, max] of ranges) {
        if (codePoint >= min && codePoint <= max) {
            return true;
        }
    }
    return false;
}

/** @type {import('CJK-util').CodepointRange} */
const KANGXI_RADICALS_RANGE = [0x2f00, 0x2fdf];

/** @type {import('CJK-util').CodepointRange} */
const CJK_RADICALS_SUPPLEMENT_RANGE = [0x2e80, 0x2eff];

/** @type {import('CJK-util').CodepointRange} */
const CJK_STROKES_RANGE = [0x31c0, 0x31ef];

/** @type {import('CJK-util').CodepointRange[]} */
const CJK_RADICALS_RANGES = [
    KANGXI_RADICALS_RANGE,
    CJK_RADICALS_SUPPLEMENT_RANGE,
    CJK_STROKES_RANGE,
];

/**
 * @param {string} text
 * @returns {string}
 */
function normalizeRadicals(text) {
    let result = '';
    for (let i = 0; i < text.length; i++) {
        const codePoint = text[i].codePointAt(0);
        result += codePoint && (isCodePointInRanges(codePoint, CJK_RADICALS_RANGES)) ? text[i].normalize('NFKD') : text[i];
    }
    return result;
}

/** @type {import('language').TextProcessor} */
const normalizeRadicalCharacters = {
    name: 'Normalize radical characters',
    description: '⼀ → 一 (U+2F00 → U+4E00)',
    process: (str) => [str, normalizeRadicals(str)],
};


